class Solution {
public:
    int ans=0;
    void dfs(TreeNode* root,int bits)
    {
        if(!root)
            return;
        if(!root->left and !root->right)
        {
            ans+=(__builtin_popcount(bits^(1<<root->val))<=1);
            return;
        }
        dfs(root->left,bits^(1<<root->val));
        dfs(root->right,bits^(1<<root->val));
    }
    int pseudoPalindromicPaths (TreeNode* root) {
        dfs(root,0);
        return ans;
    }
};
